import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Ngữ văn","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/ngu-van.md","filePath":"ideas/inquiry-ib/ngu-van.md"}'),o={name:"ideas/inquiry-ib/ngu-van.md"};function g(a,n,e,r,m,u){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="ngu-van" tabindex="-1">Ngữ văn <a class="header-anchor" href="#ngu-van" aria-label="Permalink to &quot;Ngữ văn&quot;">​</a></h1><p>Trên trang này# Ngữ văn — ba bài học inquiry theo IB <a href="#ngu-van-—-ba-bai-hoc-inquiry-theo-ib">​</a> Trong khung IB, môn này gọi là <strong>Language and Literature</strong>, và câu hỏi trung tâm của nó không phải &quot;tác phẩm này nói gì&quot; mà <strong>&quot;văn bản tạo ra hiệu ứng đó bằng cách nào?&quot;</strong> Đây là khác biệt lớn nhất so với cách dạy Văn quen thuộc. Học sinh không đi tìm ý nghĩa có sẵn để chép lại — các em điều tra cơ chế của văn bản, và bảo vệ cách đọc của mình bằng bằng chứng từ chính văn bản đó. Ý xuyên suốt cả mônVăn bản không có sẵn một ý nghĩa nằm chờ để đi tìm. Nó tạo ra hiệu ứng bằng những lựa chọn — và đọc là chỉ ra được lựa chọn nào tạo ra hiệu ứng nào. Cũng quan trọng — nhưng không phải ý lớn nhất- Người kể quyết định điều gì được thấy và điều gì bị che, nên mọi câu chuyện đều mang một góc nhìn.</p><ul><li>Ẩn dụ không phải đồ trang trí — nó định hình cách người đọc nghĩ về sự việc.</li><li>Ý nghĩa hình thành trong cuộc gặp giữa văn bản và người đọc ở một thời điểm. Đổi thời điểm thì cách đọc đổi.</li></ul><h2 id="demo-1-—-điem-nhin-ke-chuyen-cung-mot-su-viec-ba-nguoi-ke-​" tabindex="-1">Demo 1 — Điểm nhìn kể chuyện: cùng một sự việc, ba người kể <a href="#demo-1-—-điem-nhin-ke-chuyen-cung-mot-su-viec-ba-nguoi-ke">​</a> <a class="header-anchor" href="#demo-1-—-điem-nhin-ke-chuyen-cung-mot-su-viec-ba-nguoi-ke-​" aria-label="Permalink to &quot;Demo 1 — Điểm nhìn kể chuyện: cùng một sự việc, ba người kể [​](#demo-1-—-điem-nhin-ke-chuyen-cung-mot-su-viec-ba-nguoi-ke)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Perspective<strong>Related concepts</strong>Point of view · Purpose · Audience<strong>Global context</strong>Identities and relationships<strong>Statement of inquiry</strong>Người kể quyết định điều gì được thấy và điều gì bị che, nên mọi câu chuyện đều mang một góc nhìn.<strong>Cần biết trước</strong>Ngôi kể, nhân vật, cốt truyện</p><h3 id="ba-cau-hoi-​" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-cau-hoi-​" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Có những ngôi kể nào? Người kể toàn tri là gì?</li><li><strong>Conceptual:</strong> Điểm nhìn ảnh hưởng thế nào tới sự thông cảm của người đọc?</li><li><strong>Debatable:</strong> Có tồn tại một cách kể &quot;khách quan&quot; không?</li></ul><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Học sinh viết trước khi phân tích (15 phút).</strong> Giáo viên nêu một tình huống trần trụi, không cảm xúc: <em>Trong giờ ra chơi, Nam làm rơi hộp bút của Linh. Bút văng khắp sàn. Linh khóc. Cô giáo đến.</em><em>&quot;Viết lại đoạn này 150 chữ, kể từ ngôi thứ nhất. Nhóm 1 là Nam. Nhóm 2 là Linh. Nhóm 3 là một bạn đứng xem. Nhóm 4 là cô giáo.&quot;</em><strong>Bước 2 — Đọc chéo và phát hiện (15 phút).</strong> Bốn nhóm đọc bài của nhau. Giáo viên hỏi:</p><ul><li><em>&quot;Chi tiết nào có trong bản này mà không có trong bản kia?&quot;</em></li><li><em>&quot;Bản nào làm em thương Nam nhất? Cụ thể chữ nào tạo ra điều đó?&quot;</em></li><li><em>&quot;Có bản nào nói dối không? Hay tất cả đều nói thật theo cách của mình?&quot;</em> Câu cuối là câu quan trọng nhất. Học sinh nhận ra: <strong>không bản nào nói dối, nhưng bốn bản tạo ra bốn cảm giác rất khác nhau</strong> — chỉ bằng việc chọn kể gì và bỏ gì. <strong>Bước 3 — Đưa vào văn bản văn học (15 phút).</strong> Giờ mới đọc một đoạn trích thật — ví dụ một đoạn trong <em>Lão Hạc</em> kể qua điểm nhìn ông giáo. <em>&quot;Vì sao Nam Cao chọn ông giáo kể, mà không để lão Hạc tự kể? Nếu lão Hạc tự kể thì đoạn nào sẽ mất đi?&quot;</em> Học sinh đã có công cụ để trả lời — vì các em vừa tự trải nghiệm chính cơ chế đó trong bài viết của mình. <strong>Bước 4 — Tranh luận (10 phút).</strong><em>&quot;Một bản tin thời sự có điểm nhìn không? Ai đang kể?&quot;</em> Giáo viên đưa hai bản tin về cùng một sự kiện từ hai nguồn khác nhau. Học sinh áp dụng đúng bộ câu hỏi vừa dùng cho văn học. Đây là chỗ môn Văn trở thành kỹ năng sống — và trong khung IB, việc phân tích văn bản phi văn học nằm ngay trong chương trình chính thức, không phải phần mở rộng.</li></ul><h3 id="cham-theo-tieu-chi-​" tabindex="-1">Chấm theo tiêu chí <a href="#cham-theo-tieu-chi">​</a> <a class="header-anchor" href="#cham-theo-tieu-chi-​" aria-label="Permalink to &quot;Chấm theo tiêu chí [​](#cham-theo-tieu-chi)&quot;">​</a></h3><p>Tiêu chíỞ bài này<strong>A — Analysing</strong>Chỉ ra được điểm nhìn tạo hiệu ứng gì, có dẫn chứng<strong>B — Organizing</strong>Bài viết có bố cục, lập luận theo mạch<strong>C — Producing text</strong>Sáng tạo trong bài viết bốn góc nhìn<strong>D — Using language</strong>Chọn từ có chủ đích, phù hợp giọng nhân vật</p><h2 id="demo-2-—-an-du-tai-sao-khong-noi-thang-cho-xong-​" tabindex="-1">Demo 2 — Ẩn dụ: tại sao không nói thẳng cho xong? <a href="#demo-2-—-an-du-tai-sao-khong-noi-thang-cho-xong">​</a> <a class="header-anchor" href="#demo-2-—-an-du-tai-sao-khong-noi-thang-cho-xong-​" aria-label="Permalink to &quot;Demo 2 — Ẩn dụ: tại sao không nói thẳng cho xong? [​](#demo-2-—-an-du-tai-sao-khong-noi-thang-cho-xong)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Creativity<strong>Related concepts</strong>Figurative language · Theme · Style<strong>Global context</strong>Personal and cultural expression<strong>Statement of inquiry</strong>Ngôn ngữ hình ảnh truyền được những thứ mà cách nói trực tiếp làm mất đi.<strong>Cần biết trước</strong>So sánh, ẩn dụ, nhân hoá ở mức nhận diện</p><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Thử phá một bài thơ (12 phút).</strong> Giáo viên đưa một đoạn thơ có hình ảnh mạnh, rồi giao nhiệm vụ lạ: <em>&quot;Viết lại đoạn này bằng lời hoàn toàn trực tiếp. Bỏ hết hình ảnh. Giữ nguyên nội dung thông tin.&quot;</em> Học sinh làm, và kết quả luôn nhạt hơn hẳn. <em>&quot;Nội dung thông tin vẫn nguyên. Vậy cái gì đã mất?&quot;</em> Đây là cách hiệu quả nhất để dạy về ẩn dụ: <strong>không phân tích cái đang có, mà phá nó đi rồi xem cái gì biến mất</strong>. <strong>Bước 2 — Thu thập từ đời sống (10 phút).</strong><em>&quot;Liệt kê 10 ẩn dụ em dùng hằng ngày mà không nghĩ đó là ẩn dụ.&quot;</em> Học sinh thường bí lúc đầu, rồi ra hàng loạt: &quot;thời gian trôi&quot;, &quot;giá cả leo thang&quot;, &quot;tôi đang chìm trong bài tập&quot;, &quot;mạng bị nghẽn&quot;, &quot;ý tưởng nảy ra&quot;. <em>&quot;Thời gian có thật sự &#39;trôi&#39; không? Nó chảy đi đâu?&quot;</em><strong>Bước 3 — Ẩn dụ định hình cách nghĩ (15 phút).</strong> Giáo viên đưa hai cách nói về một cuộc tranh luận:</p><ul><li><em>&quot;Anh ta tấn công lập luận của tôi. Tôi phản công. Tôi thắng.&quot;</em></li><li><em>&quot;Chúng tôi cùng xây dựng ý tưởng. Chúng tôi đi tới một chỗ chung.&quot;</em><em>&quot;Hai cách nói này khiến ta hành xử khác nhau thế nào trong một cuộc tranh luận thật?&quot;</em> Đây là một trong những ý tưởng sâu nhất mà môn Văn có thể đưa cho học sinh: ẩn dụ không chỉ trang trí — nó <strong>định hình cách ta suy nghĩ về sự việc</strong>. <strong>Bước 4 — Áp dụng lên tác phẩm (15 phút).</strong> Quay lại tác phẩm đang học. <em>&quot;Tác giả dùng cụm ẩn dụ nào lặp lại? Cụm đó khiến người đọc nghĩ về nhân vật theo hướng nào?&quot;</em><strong>Bước 5 — Tự viết (10 phút).</strong><em>&quot;Viết ba câu về cùng một cảm xúc: một câu nói thẳng, một câu dùng ẩn dụ về nước, một câu dùng ẩn dụ về ánh sáng. Cái nào em thấy đúng nhất với cảm xúc của em?&quot;</em></li></ul><h2 id="demo-3-—-van-ban-va-boi-canh-mot-tac-pham-đoc-o-hai-thoi-điem-​" tabindex="-1">Demo 3 — Văn bản và bối cảnh: một tác phẩm đọc ở hai thời điểm <a href="#demo-3-—-van-ban-va-boi-canh-mot-tac-pham-đoc-o-hai-thoi-điem">​</a> <a class="header-anchor" href="#demo-3-—-van-ban-va-boi-canh-mot-tac-pham-đoc-o-hai-thoi-điem-​" aria-label="Permalink to &quot;Demo 3 — Văn bản và bối cảnh: một tác phẩm đọc ở hai thời điểm [​](#demo-3-—-van-ban-va-boi-canh-mot-tac-pham-đoc-o-hai-thoi-điem)&quot;">​</a></h2><p><strong>Lớp</strong>10–12<strong>Key concept</strong>Connections<strong>Related concepts</strong>Context · Audience · Intertextuality<strong>Global context</strong>Orientation in space and time<strong>Statement of inquiry</strong>Ý nghĩa của một văn bản không nằm cố định trong nó, mà hình thành trong cuộc gặp giữa văn bản và người đọc ở một thời điểm cụ thể.<strong>Cần biết trước</strong>Đã đọc trọn vẹn một tác phẩm; khái niệm bối cảnh sáng tác</p><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Đọc mù (12 phút).</strong> Giáo viên đưa một văn bản ngắn <strong>không</strong> kèm tên tác giả, năm sáng tác, hay bất kỳ chú thích nào. <em>&quot;Đọc và viết ba câu: văn bản này nói về gì, người viết cảm thấy thế nào, và em đoán nó được viết khi nào.&quot;</em><strong>Bước 2 — Đưa bối cảnh, đọc lại (12 phút).</strong> Giờ mới đưa thông tin: tác giả là ai, viết năm nào, trong hoàn cảnh gì. <em>&quot;Đọc lại. Câu nào giờ có nghĩa khác? Chi tiết nào trước đây em bỏ qua mà giờ thành quan trọng?&quot;</em> Sự thay đổi thường rất rõ, và học sinh tự cảm nhận được nó — thay vì được nghe giảng rằng &quot;bối cảnh quan trọng&quot;. <strong>Bước 3 — Câu hỏi khó (15 phút).</strong><em>&quot;Vậy cách đọc đầu tiên của em có sai không?&quot;</em> Đây là câu hỏi mở thật sự, và lớp thường chia phe. Một phe nói sai vì thiếu thông tin. Phe kia nói không sai — người đọc năm 2026 vốn đọc bằng con mắt năm 2026. Giáo viên không kết luận. Thay vào đó: <em>&quot;Nếu 100 năm nữa có người đọc văn bản này, họ có đọc giống em không? Cách đọc của họ có sai không?&quot;</em><strong>Bước 4 — Bài viết đánh giá (làm ở nhà).</strong><em>&quot;Chọn một chi tiết trong tác phẩm. Trình bày hai cách đọc chi tiết đó — một theo bối cảnh sáng tác, một theo mắt người đọc hôm nay. Bảo vệ cả hai bằng dẫn chứng từ văn bản, rồi nói cách nào em thấy thuyết phục hơn và vì sao.&quot;</em> Đề bài này là đặc trưng IB: nó <strong>không</strong> hỏi &quot;ý nghĩa của tác phẩm là gì&quot;, mà yêu cầu học sinh xây dựng và bảo vệ một cách đọc — và thừa nhận rằng có nhiều cách đọc hợp lệ. Điều đáng lấy cho gia đình Demo 1 làm được ở nhà trong 20 phút với bất kỳ chuyện gì vừa xảy ra: <em>&quot;Kể lại chuyện lúc nãy theo lời em con xem.&quot;</em> Nó dạy một điều mà rất ít bài học nào dạy trực tiếp: người kể luôn có góc nhìn — kể cả chính mình. <a href="/ideas/inquiry-ib/tieng-anh">Tiếng Anh →</a></p>',21)])])}const b=t(o,[["render",g]]);export{l as __pageData,b as default};
